Office.actions.associate("signaturEinfuegen",function(e){try{Office.context.mailbox.item.body.setSignatureAsync('\n    <div style="font-family:Arial,sans-serif;font-size:12px;color:#333;">\n      <p>Mit freundlichen Grüßen</p>\n      <p>\n        <strong>Max Mustermann</strong><br>\n        Stadtgemeinde Deutsch-Wagram\n      </p>\n      <p>\n        <a href="https://www.deutsch-wagram.gv.at">\n          www.deutsch-wagram.gv.at\n        </a>\n      </p>\n    </div>\n  ',{coercionType:Office.CoercionType.Html},function(n){n.status===Office.AsyncResultStatus.Failed&&console.error("Signaturfehler:",n.error),e.completed()})}catch(n){console.error("Fehler:",n),e.completed()}});